import hashlib,json,shutil
from pathlib import Path
O=Path(__file__).resolve().parent;OLD=O.parent/'v14-nekovar-cochain-inputs-author-001'
def sha(b):return hashlib.sha256(b).hexdigest()
def dig(x):return sha(json.dumps(x,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode())
def save(n,x):(O/n).write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
for p in OLD.iterdir():
 if p.is_file() and p.name not in ['author.py','MANIFEST.json']:shutil.copyfile(p,O/p.name)
c=json.loads((O/'COMPONENTS.json').read_bytes());x=c[0]
argument='''For K10 take R=Z_2[[Gamma]][G]=Z_2[[t]][G], where G is the fixed finite elementary abelian two-group, and take the free rank-two R-module T_2E tensor R with the actual continuous chi_0 psi kappa^(-1) action. R is a complete noetherian local ring with maximal ideal m generated by2,t and g-1 for g in G; its residue field is F_2. The actual finite quotients use J_(a,n)=(2^a,(1+t)^(2^n)-1). The quotient R/J_(a,n) is finite and local: modulo2 it is the group algebra of the finite two-group Gamma_n times G, whose augmentation ideal is nilpotent. Hence some power of m is contained in J_(a,n). Conversely J_(a,n) is contained in any prescribed m^k for a,n sufficiently large: 2^a is in m^k for a>=k, while for 1<=i<k the coefficient binomial(2^n,i) has valuation at least n-v_2(i), and terms of degree i>=k are already in m^k. Thus these ideals and the m-adic powers define cofinal filtrations. Use a diagonal cofinal sequence in a,n. Each H0 of the finite quotient coefficient is a subgroup of a finite module, so its images stabilize and lim1 H0 vanishes. Apply Corollary4.1.3 to the complete finite-type admissible R-module through this cofinal identification. Norm compatibility of the already supplied classes produces their inverse-limit element; the argument proves no new norm relation.'''
x['use']['reason']+=' '+argument;x['connection']['use_sha256']=dig(x['use'])
save('COMPONENTS.json',c);save('TOPOLOGY-APPLICATION.json',{'use_id':x['use']['id'],'argument':argument,'scope':'Only the actual completed K10 coefficient topology and inverse-limit passage; source hypotheses retained.'})
save('DELTA.json',{'old_manifest_sha256':sha((OLD/'MANIFEST.json').read_bytes()),'change':'Add explicit ring/module and cofinal topology justification to inverse-limit use reason and update its use hash. No source assertion or location changes; other three components identical.'})
save('CHECKS.json',{'components':len(c),'use_hashes':all(dig(y['use'])==y['connection']['use_sha256'] for y in c)})
save('MANIFEST.json',{'files':{p.name:{'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size} for p in sorted(O.iterdir()) if p.is_file() and p.name!='MANIFEST.json'}})
print(sha((O/'MANIFEST.json').read_bytes()))
